  const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const windows = rows(data.slot_windows);
  const windowLabels = windows.map(window => {
    const weekday = dayNames[Number(window.weekday)] || 'Selected day';
    const hour = Number(window.hour); const minute = Number(window.minute || 0);
    const displayHour = hour % 12 || 12; const suffix = hour >= 12 ? 'PM' : 'AM';
    return `${weekday} at ${displayHour}:${String(minute).padStart(2, '0')} ${suffix}`;
  });
